#@ requires 1 == 1
    #@ ensures \length(stmts) == 0 ==> \result == 0
    #@ assigns \nothing
    def uses_break(stmts: List[Dict[str, Any]]) -> bool:
        found = False
        i = 0
        n = len(stmts)
        #@ loop invariant 0 <= i and i <= n
        #@ loop variant n - i
        while i < n and not found:
            stmt = stmts[i]
            if stmt["stmt"] == "Break":
                found = True
            if not found:
                if "body" in stmt and IRScanner.uses_break(stmt["body"]):
                    found = True
            if not found:
                if "orelse" in stmt and IRScanner.uses_break(stmt["orelse"]):
                    found = True
            i += 1
        return found
